mapper.select:
SELECT tp.policy_code, tp.policy_name, tp.source_type, CASE WHEN tp.source_type = 'DEPT' THEN sd.dept_code WHEN tp.source_type = 'ROLE' THEN sr.role_code ELSE NULL END AS source_code, CASE WHEN tp.source_type = 'DEPT' THEN sd.dept_name WHEN tp.source_type = 'ROLE' THEN sr.role_name ELSE NULL END AS source_name, st.tenant_code, st.tenant_name, tp.bind_time, tp.status, tp.disable_reason, cu.user_name AS create_by_name, tp.create_at, uu.user_name AS update_by_name, tp.update_at, tp.is_deleted, tp.deleted_at FROM sys_tenant_policy tp LEFT JOIN sys_tenant st ON tp.tenant_id = st.id AND st.is_deleted = 'NOT_DELETED' LEFT JOIN sys_dept sd ON tp.source_type = 'DEPT' AND tp.source_id = sd.id AND sd.is_deleted = 'NOT_DELETED' LEFT JOIN sys_role sr ON tp.source_type = 'ROLE' AND tp.source_id = sr.id AND sr.is_deleted = 'NOT_DELETED' LEFT JOIN sys_user cu ON tp.create_by = cu.id AND cu.is_deleted = 'NOT_DELETED' LEFT JOIN sys_user uu ON tp.update_by = uu.id AND uu.is_deleted = 'NOT_DELETED' WHERE tp.is_deleted = 'NOT_DELETED'
AND tp.source_type = #{sourceType}
AND tp.source_id = #{sourceId}
AND tp.tenant_id = #{tenantId}
AND tp.status = #{status}
ORDER BY tp.create_at DESC
